const projectKinds={'michigan-advertising-marketing':['Student Organization','Website','Internal Tool','Individual'],maizebus:['Mobile App','Student-built','Founding Designers','Team'],solstove:['Internship','Mobile App','Sole Designer'],snuffed:['Hackathon Project','Mobile App','Landing Page','Team']};
const projects=[
 {slug:'michigan-advertising-marketing',title:'Michigan Advertising & Marketing',role:'Design Engineer',desc:'Unifying a scattered recruiting process',type:'mam',facts:['Design Engineer','Aug 2026 –\nSep 2026','Figma Design\nLovable\nClaude','I built a recruiting evaluation system that reduced deliberation times by 40%.'],skills:'',sections:[
 ['CONTEXT',{type:'heading',text:'A growing applicant pool relied on a manual recruiting process.'},{type:'text',text:'Michigan Advertising and Marketing (MAM) is a student marketing club whose applications have grown about 10% on average over the past four semesters.'},{type:'text',text:'Our recruitment process has always been fully manual: Applications were received using Google Forms, notes were taken in Google Sheets, resources stored in Notion, and coordination occurred in Gmail and iMessages.'}],
 ['PROBLEM',{type:'heading',text:'This scattered recruiting process made it difficult to talk through decisions without constantly back-tracking.'},{type:'image',src:'workflow-tabs-text.png?v=light-gray-bg',alt:'MAM recruiting workflow spread across forms, spreadsheets, documents, and email tabs'},{type:'text',text:'By final deliberations, a candidate\'s record was split across many tabs: their application in one place, their group interview rubric scores in another, and interview notes somewhere else. The recruitment team spent as much time hunting for information as they did discussing applicants.'}],
 ['OPPORTUNITY',{type:'heading',text:"Consolidate candidate evaluation into one platform to improve the team's collaborative decision-making speed and confidence."},{type:'text',text:"By assessing and extracting the most useful features of each previously used platform, one centralized recruitment dashboard can optimize MAM's recruitment process. The team can run all their evaluations across the four phases without constantly switching tabs."},{type:'image',src:'mam-application-flow.png?v=light-gray-bg',alt:'MAM application form and application submission confirmation'},{type:'goals',intro:'I approached this redesign project with two main goals:',goals:[{title:'Support asynch communication while protecting independent judgment.',text:'Prevent biased decision-making by temporarily disabling certain features.'},{title:'Build for the long term by frequently incorporating modularity.',text:'I wanted a tool that future recruitment teams could keep using.'}]}],
 ['SOLUTION',{type:'heading',text:"A shared dashboard that brings every applicant's record and every recruiter's notes together"},{type:'text',text:"The dashboard consists of MAM's recruitment process across five tabs: (Open) event attendance, application review, group interviews, individual interviews, and final decisions."},{type:'text',text:'Each stage has its own evaluation tools based on informal interviews with the recruitment team that audited the uniquely helpful features used in the previous platforms.'},{type:'text',text:"Each applicant's profile carried their information from earlier stages, allowing recruiters to review a candidate's full history without leaving the dashboard."},{type:'heading',text:'Evaluate on your own accord first'},{type:'text',text:"Each recruiter's evaluation starts as a private note, a 1–5 overall rating, and a Yes / No / Maybe on moving forward. Other recruiters' notes stay hidden until you submit your own so that every mark reflects an independent read of the applicant."},{type:'text',text:'The dashboard header tracks what each recruiter has committed, as well as what is still in progress so that recruiters must be confident in their evaluations before releasing them publicly for others to see.'},{type:'placeholder',text:"Video of other reviewers' reveal after submitting your notes"},{type:'heading',text:'View the team consensus'},{type:'text',text:"Once everyone's marks are submitted, the Team marks summary groups applicants by agreement, like \"Largely accepted\", with vote counts and the initials of each reviewer. These individual judgments become an indicator of group consensus (either prompting discourse or unanimous advancement) only after everyone has committed to their own."},{type:'video',src:'mam-submit-marks-smoothed_1.mp4',alt:'Recruitment dashboard team consensus revealed after submitting marks'},{type:'heading',text:'Designing for scalability and longevity'},{type:'text',text:"Building in Lovable made it tempting to hard-code applicant info, interview questions, and stage transitions to publish things faster, but a hard-coded tool wouldn't have been usable after this one cycle."},{type:'text',text:'So, I made the parts that change every semester editable from inside the dashboard, including applicant data, interview content, logistics, movement between stages, and imported notes.'},{type:'placeholder',text:'(Toggles)'},],
 ['PROCESS',{type:'heading',text:'From vibecoding on Lovable to refining on Figma'},{type:'process-tabs'}],
 ['RESULT',{type:'heading',text:'The MAM Recruitment Dashboard: one source of truth for the entire recruiting cycle'},{type:'text',text:"The dashboard ran MAM's full fall 2026 recruitment cycle. 14 recruiters used it to evaluate 133 applications through group and individual interviews, narrowing the pool down to 25 new members."},{type:'text',text:'By embedding the application, staging what reviewers see and when, and making every seasonal detail editable, the dashboard turned a four-platform manual process into a single collaborative workflow that the next team can inherit.'}],
 ['IMPACT',{type:'heading',text:'<span class="mam-impact-row"><strong class="mam-impact-number" data-countup="133">0</strong><span>applicants reviewed</span></span><span class="mam-impact-row"><strong class="mam-impact-number" data-countup="25">0</strong><span>members accepted</span></span><span class="mam-impact-row"><strong class="mam-impact-number" data-countup="47">0</strong><span>% less time spent deliberating</span></span>'},{type:'text',text:'The new system decreased evaluation meeting times by around 2 hours per recruitment phase, and all 14 recruiters (100%) reported being satisfied with it in a survey at the end of the process.'},{type:'text',text:"However, the most valuable finding for me wasn't necessarily speed, it was that recruiters said that always being able to access all of an applicant's information in one place made them trust their own decisions, and the group's final decisions, more confidently. This shift in decision-making between stages is ultimately what made the process both faster and more satisfying."}],
 ['LEARNING',
  {type:'lesson',heading:'Visibility, or the lack thereof, as a design decision',body:"I went into this project thinking consolidation meant showing everything, because as I mentioned, we wanted one place for all the information. Instead, I realized the most important decisions were about what not to show yet; deciding when a recruiter sees their teammates' notes shaped the team's trust in the final outcome more than anything else.",visuals:[{src:'mam-visibility-team-selfie.jpg',alt:'Two MAM teammates smiling together during a recruiting event'}, {src:'mam-visibility-team-review.jpg',alt:'MAM members collaborating around a table during recruitment'}]},
  {type:'lesson',heading:'Designing AND building a large-scale tool at the same time (for the first time)',body:"Building the dashboard myself in Lovable meant every design decision had an immediate engineering risk. To ensure the tool could be used for future recruitment teams after I'm no longer there to explain how everything works, I chose editable, modular features over hard-coded ones, even though they were often more convenient to implement on my end. Receiving feedback throughout the recruitment cycle made me increasingly careful about accounting for setbacks and required lots of usability testing. Despite my previous unfamiliarity with designing this kind of product, I've realized it may just be what I want to explore more of!",visuals:[{src:'mam-design-build-team.jpg',alt:'Michigan Advertising and Marketing members gathered together at a club event'}]},
 ]

 ]},
 {slug:'maizebus',title:'MaizeBus',role:'UX Designer',desc:'Simplifying transit data into directions students trust',type:'maize',facts:['UX Designer','June 2026 – August 2026','Figma Design · FigJam Cosmos · GitHub','I designed MaizeBus’s Travel Mode live-navigation UI, contributing to a 200% download increase after launch.'],tldrFull:'Travel Mode shipped as part of MaizeBus 3.0, with all three features — the progress bar, dynamic route directions, and route confirmation — working together to build user trust in a new, non-university-affiliated app. The design was validated through over 40 usability tests before launch, ensuring the interface was legible, familiar, and low-friction for students navigating a new campus. By borrowing conventions from trusted apps like Google and Apple Maps, handling ghost bus errors non-invasively, and surfacing only the most relevant information at each step of a trip, Travel Mode turned MaizeBus\' data advantage into a tangible, trustworthy user experience.',sections:[
 ['CONTEXT',{type:'heading',text:'Thousands of students at UofM currently rely on buses to get to class using an university transit app.'},{type:'text',text:'Many UofM students take the bus to get to class, requiring them to get familiarized with public transportation, remembering all the bus routes, and navigating unprecedented delays.'},{type:'text',text:'On top of adjusting to a new environment and lifestyle, the difficulty of getting places adds an additional, unnecessary stressor to students\' existing ones — especially on a campus as large as Ann Arbor.'},{type:'text',text:'MBus, the app students are currently told to use, simply displays bus tracking data using the university’s bus API. It often shows inaccurate arrival times and doesn’t help students learn their routes.'},{type:'text',text:'Dedicated to bringing a more reliable alternative to campus, I worked alongside 20 student developers as one of two designers to build MaizeBus, an app made for students, by students.'}],
 ['OPPORTUNITY',{type:'heading',text:'Help students confidently navigate campus by working around unreliable bus data through dynamic UX/UI.'},{type:'text',text:'But, this begged the question: Why would students rely on it over an official university app?'},{type:'text',text:'As a new app without university affiliation, my focus was turning the wealth of additional, complex data collected by MaizeBus into intentional, trustworthy features that helped students move across campus with confidence.'}],
 ['SOLUTION',{type:'heading',text:'Clear, familiar route cues made complex travel data easy to trust'},{type:'text',text:'Travel Mode translated a large, unreliable stream of route data into a few clear cues:'},{type:'cue-cards',items:[{title:'Where you are',text:'See your place in the trip, with completed and upcoming steps.'},{title:'What to do next',text:'Follow the next stop or action in a clear sequence.'},{title:'When to expect arrival',text:'Check the arrival estimate as the trip progresses.'}]},{type:'text',text:'Familiar patterns and progressive detail let students understand each step as they moved, while the interface handled the backend complexity. This way, students could trust the app through without recognition without needing a separate onboarding tutorial.'}],
 ['FEATURE','Horizontal progress bar','MaizeBus stood apart with building search. The university app showed only where and when buses would arrive, leaving students to work out how to get from A to B on their own.','MaizeBus let students search for specific buildings, but its directions were still a static, segmented list. Students could find a destination without getting clear, step-by-step guidance to reach it.','I designed a live navigation flow with a horizontal progress bar and sequential guidance cards. To make the route data digestible and easy to learn, I prioritized the details students needed at each step, surfacing the next cue as their trip progressed.',{type:'before-image',index:1,src:'maizebus-progress-before.png',alt:'MaizeBus earlier horizontal progress bar screen'},{type:'before-image',index:2,src:'maizebus-progress-before-2.png',alt:'MaizeBus route progress screen with walking cue and arrival time'},{type:'before-image',index:3,src:'maizebus-progress-before-3.png',alt:'MaizeBus route progress screen with five stops and arrival time'}],
 ['FEATURE','Dynamic route directions page','After expanding the progress modal, the detailed directions page required decision-making about sequencing and hierarchy to prioritize which information stayed visible and when.', 'The redesign uses the user\'s live status to cut already-passed steps instead of keeping the full list on screen the whole ride, and grouping intermediate stops with dividers.',{type:'video',src:'maizebus-journey.mp4',alt:'MaizeBus dynamic route directions journey'}],
 ['FEATURE','Route confirmation','The university’s bus-tracking API produced “ghost buses,” a recurring source of frustration in interviews: buses that appeared in the app but never arrived, or arrived without appearing. This left students missing or chasing buses.', 'To address this without disrupting the journey or undermining confidence, I explored two approaches:', {type:'approach',label:'Initial',heading:'A proactive modal',text:'Appears when the user leaves the stop, asking, “Which bus are you on?”'}, {type:'approach',variant:'final',label:'Final',heading:'Lower friction, passive banner',text:'Shown only when the user begins to stray from the intended route.'}, {type:'video',src:'maizebus-reroute.mp4',alt:'MaizeBus route confirmation flow'}],
 ['RESULT',{type:'heading',text:'Travel Mode: a three-feature navigation flow that accommodated inaccurate APIs'},{type:'text',text:'Travel Mode shipped as part of MaizeBus 3.0, with all three features — the progress bar, dynamic route directions, and route confirmation — working together to build user trust in a new, non-university-affiliated app.'},{type:'text',text:'The design was validated through over 40 usability tests before launch, ensuring the interface was legible, familiar, and low-friction for students navigating a new campus.'},{type:'text',text:'By borrowing conventions from trusted apps like Google and Apple Maps, handling ghost bus errors non-invasively, and surfacing only the most relevant information at each step of a trip, Travel Mode turned MaizeBus’ data advantage into a tangible, trustworthy user experience.'}],
 ['IMPACT',{type:'heading',text:'10x daily downloads in the week following version updates'},{type:'text',text:'After shipping Travel Mode in MaizeBus 3.0, we saw clear signs that trust in the product was improving.'},{type:'text',text:'At our annual club fair, nearly every student we spoke with who already used the university app told us they’d switch to MaizeBus after seeing the new Travel Mode experience.'},{type:'metric',from:'30',to:'300',factor:'10×',label:'average daily downloads'}],
 ['WHAT I LEARNED ABOUT…',{type:'heading',text:'Balancing uniqueness and distinction with familiarity and trust'},{type:'text',text:'We wanted MaizeBus to feel distinct from MBus, with a unique system and intuitive experience, but users struggled with our original progress bar. For a new app, trust mattered more than novelty: borrowing familiar patterns from Google and Apple Maps made routes easier to follow and better served students’ travel needs.'},{type:'heading',text:'Collaboration and communication as one of the only designers'},{type:'text',text:'Working as one of two designers on a 20-person developer team taught me that design depends as much on communication and prioritization as interface decisions. I partnered closely with my co-designer to balance backend constraints—especially for route confirmation—and prepared carefully to advocate for key details during developer handoff.'},{type:'heading',text:'Tangible evidence of meeting goals and user needs'},{type:'text',text:'As one of two designers, I wore many hats and knew the product inside and out, which sometimes led me to assume a design was intuitive. Testing with more than 40 students helped me step back, respond to diverse experiences, and bring evidence—not assumptions—to the club fair. Conversion results later reinforced that the redesign worked.'}]
 ]},
 {slug:'snuffed',title:'Snuffed',role:'UX Designer',desc:'Helping users pause before impulse purchases',type:'snuffed',facts:['Designer','2 designers · 2 engineers','Codex · Cursor · Claude · Figma · Cosmos','Information architecture, app direction, landing page'],links:[{label:'Demo video',url:'assets/media/snuffed/snuffed_walkthrough_full.mp4',embedUrl:'assets/media/snuffed/snuffed_walkthrough_full.mp4',kind:'video'},{label:'App',url:'https://snuff-mobile.expo.app',embedUrl:'https://snuff-mobile.expo.app',kind:'app'},{label:'Landing page',url:'https://www.snuffed.tech/',embedUrl:'https://www.snuffed.tech/',kind:'site'},{label:'Pitch deck',url:'assets/media/snuffed/snuffed-pitch.pdf',embedUrl:'assets/media/snuffed/snuffed-pitch.pdf',kind:'pdf'},{label:'Devpost',url:'https://devpost.com/software/snuffed',embedUrl:'https://devpost.com/software/snuffed',kind:'devpost'}],sections:[
  ['Context',{type:'heading',text:'At MHacks 2026, our four-person team had 24 hours to respond to the FinTech prompt:'},{type:'prompt',text:'“Money, reimagined. Build tools that make finance faster, fairer, and more accessible for everyone.”'},{type:'text',text:'I guided our information architecture to ensure the product experience was consistently tied to our financial access goals. Additionally, I helped build the app prototype with my team and created the landing page that bridged our product components.'},{type:'snuffed-timeline',total:1800,events:[{time:'Oct. 3 · 12 PM',start:0,duration:'3h',minutes:180,kind:'work',text:'Team brainstorming'},{time:'3 PM',start:180,duration:'3h',minutes:180,kind:'work',text:'Ideating + wireframing'},{time:'6 PM',start:360,duration:'1h 30m',minutes:90,kind:'break',text:'Dinner break'},{time:'7:30 PM',start:450,duration:'9h',minutes:540,kind:'work',text:'Building with blood, sweat, and RedBulls'},{time:'Oct. 4 · 4:30 AM',start:990,duration:'3h',minutes:180,kind:'break',text:'Power nap'},{time:'7:30 AM',start:1170,duration:'3h',minutes:180,kind:'work',text:'Assembling pitch and sponsor decks'},{time:'10:30 AM',start:1350,duration:'1h 30m',minutes:90,kind:'work',text:'Writing Devpost submission'},{time:'12 PM',start:1440,duration:'1h',minutes:60,kind:'milestone',text:'Tossing our Redbulls'},{time:'1 PM',start:1500,duration:'2h',minutes:120,kind:'work',text:'Pitching to judges'},{time:'Oct. 4 · 4:30 PM',start:1710,duration:'1h 30m',minutes:90,kind:'win',text:'WINNING FINTECH TRACK!'}]}],
  ['Problem',{type:'snuffed-problem',heading:'Nowadays, a purchase is just one click away — it\'s almost too easy.',intro:['We’ve all experienced a time when we caved in to a transaction and realized we could’ve easily lived without it. Whether it was a new sweater in a color you’ve never worn, a bet on your hometown team, or simply a sweet treat, spending is now dangerously easier than ever.'],stats:[{value:'92%',description:'of the population impulse-spends'},{value:'~$1,800',description:'wasted annually on unplanned purchases'}]}],
  ['Opportunity',{type:'heading',text:'Create room for long-term financial growth by making spending more intentional.'},{type:'text',text:'The hackathon challenge was to build tools that make finance faster, fairer, and more accessible for everyone. Most FinTech focuses on growing money — investing, crypto, digital wallets, and beyond — but growth depends on having money to grow in the first place, and that money often slips away in impulse spending.'},{type:'text',text:'We noticed that impulses are social; people are more likely to spend or gamble when others around them are doing it too. So, we asked: what if that same social pull helped people resist instead?'},{type:'image',src:'snuffed/snuffed-brainstorming.png',alt:'Brainstorming sketch connecting faster, fairer, and accessible financial tools to three idea branches.'}],
  ['Solution',{type:'heading',text:'Snuffed turns saving into a shared challenge, encouraging people to pause before a purchase without actually taking the decision away from them.'},{type:'text',text:'The mobile app tracks spending and builds motivation with a flame buddy and leaderboard. Users download the Chrome extension from the landing page to pause at checkout, then can reach out to friends through iMessage for support before deciding whether to proceed.'},{type:'snuffed-storyboard',steps:[{image:'snuffed/flame-companion.png',video:'snuffed/snuffed-score-motion-trimmed.mov',alt:'Looping Snuffed app animation showing the flame buddy, Snuff Score, weekly savings, and progress graph.',eyebrow:'Component 1',title:'Snuffed mobile app',text:'The mobile app uses a gamification model to track users’ spending habits, personalize a “flame buddy”, and compete against friends in a weekly leaderboard.'},{image:'snuffed/checkout-pause.png',alt:'Snuffed Chrome extension checkout pause with options to pause, ask a friend, or save the item.',eyebrow:'Component 2',title:'Chrome extension landing page',text:'Users can visit Snuffed’s landing page to download the Chrome extension that blocks purchases before committing on sites where they’re likely to impulse-spend.'},{image:'snuffed/friend-checkin.png',alt:'Snuffed iMessage check-in where a friend offers encouragement while leaving the purchase decision to the shopper.',eyebrow:'Component 3',title:'Support contact via iMessage agent',text:'Before proceeding with a purchase, the app encourages users to think twice while their friends help keep them accountable.'}]}],
  ['Mobile App',{type:'snuffed-app-breakdown',heading:'A companion that makes intentional spending feel rewarding.',intro:'The mobile app guides users from onboarding to a weekly routine: meet a flame buddy, track saved money, compare progress with friends, revisit saved items, and tune reminders.',pages:[{title:'Start with Snuffed',text:'A warm welcome introduces the idea: pause before impulse spending and make room for what matters.',image:'snuffed/mobile-screens/01-welcome.png',alt:'Welcome screen for Snuffed, with the flame buddy and the message “snuff your impulse spending.”'},{title:'Make space',text:'A quick sign-up flow lets people create an account or continue as a guest.',image:'snuffed/mobile-screens/02-sign-in.png',alt:'Snuffed sign-in screen with options to continue with Google, Apple, or as a guest.'},{title:'See your progress',text:'The home screen brings the flame buddy, Snuff Score, savings total, and weekly progress into one view.',image:'snuffed/mobile-screens/03-home.png',alt:'Snuffed home screen with flame buddy, Snuff Score, weekly savings, and progress graph.'},{title:'Save together',text:'A friends leaderboard turns small pauses into a friendly shared challenge.',image:'snuffed/mobile-screens/04-friends.png',alt:'Snuffed friends leaderboard showing weekly savings comparisons.'},{title:'Revisit saved items',text:'A personal collection keeps considered purchases available to revisit later.',image:'snuffed/mobile-screens/05-saved-items.png',alt:'Snuffed saved items screen with a table light and camera to revisit.'},{title:'Make it yours',text:'Profile settings let users personalize their flame and choose how often they want reminders.',image:'snuffed/mobile-screens/06-profile.png',alt:'Snuffed profile screen with flame customization and reminder settings.'}]}],
  ['Result',{type:'heading',text:'Snuffed won the FinTech Track at MHacks 2026.'},{type:'text',text:'By the end of the hackathon, we had a connected product concept and a working demo flow that brought the intervention and mobile companion together. The prototype used a controlled checkout experience to demonstrate the idea; it was not a broadly released shopping product.'},{type:'text',text:'The next step would be testing the pause with shoppers and expanding merchant coverage carefully, while checking how often checkout detection misses or interrupts a purchase.'},{type:'submission-tabs'}],
  ['REFLECTION',{type:'heading',text:'A useful pause should support someone’s own intention, not make the choice for them.'},{type:'text',text:'Building on a hackathon timeline pushed us to make the interaction legible quickly and keep the demo scope focused. The most important product decision was preserving a clear path to continue: social support and scoring can encourage reflection, but the shopper makes the final call.'}]
 ]},
 {slug:'solstove',title:'SolStove: IoT Pairing App',role:'UI Designer for SolStove',desc:'Making premier clean cooking technology accessible and trustworthy for families in Guatemala.',type:'sol',prototypeUrl:'https://www.figma.com/proto/FOX6PfyJkMqx98g7O5m1Qw/SolStove-Prototyping?node-id=274-231&viewport=427%2C365%2C0.19&t=81pmzVyhr2cGBYWX-1&scaling=scale-down&content-scaling=fixed&starting-point-node-id=274%3A230&page-id=274%3A230',facts:['UI Designer for SolStove','Sep. 2025 – Dec. 2025','Figma · FigJam · Google Slides','User Research · UI Design · Hi-Fi Prototyping'],skills:'User Research · UI Design · Hi-Fi Prototyping',sections:[
 ['PROBLEM',{type:'heading',text:'Clean cooking solutions remain out of reach for the families who need them most.'},{type:'text',text:'Indoor air pollution from uncontained biomass fires detrimentally impacts millions of people every year. Biomass cooking contributes 2–3% of global greenhouse gas emissions, while women and children spend significant portions of their time and income sourcing fuel instead of pursuing education or economic opportunity.'},{type:'text',text:'After working on clean cooking with families in Guatemala for four years, a SolStove founder realized that clean cooking solutions exist, yet remain inaccessible. There is a need for a low-cost, culturally resonant solution built to scale and designed to prove its impact over time.'}],
 ['OPPORTUNITY',{type:'heading',text:'Build familiarity and confidence through a clear, culturally aware pairing experience.'},{type:'text',text:'Electric cooking appliances are new to many of the communities SolStove serves, so the e-pairing app could not assume any baseline familiarity. Each interaction needed to reduce first-use friction and build confidence through clear feedback, helping community members gradually trust the application, business model, and company values.'}],
 ['RESEARCH',{type:'heading',text:'Local families revealed four barriers to adopting clean cooking.'},{type:'text',text:'More than 60 interviews and 90 surveys with local families, clean-cooking experts, and social entrepreneurs informed four structural barriers:'},{type:'list',items:['Cost: upfront prices for current solutions are incredibly high.','Culture: existing products often fail to account for local cooking practices and preferences.','Education: awareness of clean-cooking technology benefits is critically low.','Scalability: distribution networks are limited, and long-term impact is rarely tracked.']},{type:'image',src:'solstove/user-persona.png',alt:'SolStove user persona describing a Guatemalan mother, her cooking habits, and key pain points.'}],
 ['SYNTHESIS',{type:'heading',text:'SmartHQ showed how to make an unfamiliar connected appliance easier to use.'},{type:'text',text:'A SWOT analysis and exploration of SmartHQ, a mobile app for managing Wi-Fi-enabled appliances, informed UX insights related to usability, navigation, and onboarding.'},{type:'text',text:'I focused on how the interface could support people unfamiliar with device pairing and connected ecosystems, identifying opportunities to improve learnability and accessibility.'},{type:'image',src:'solstove/smarthq-swot.png',alt:'SWOT analysis of the SmartHQ app, highlighting usability strengths, navigation weaknesses, and opportunities.'},{type:'image',src:'solstove/smarthq-exploration.png',alt:'SmartHQ app exploration study across onboarding, device setup, account, and energy screens.'}],
 ['IDEATING',{type:'heading',text:'A clear, welcoming visual system can make setup feel approachable.'},{type:'text',text:'Beyond usability, I evaluated interface styles and features that could support the SolStove brand and its audience. I looked for strong organization through thoughtful grouping and clear content hierarchy, balanced with welcoming elements such as rounded containers and friendly language.'},{type:'image',src:'solstove/moodboard.png',alt:'Moodboard exploring interface directions, color, layout, and onboarding patterns.'},{type:'image',src:'solstove/style-guide.png',alt:'SolStove visual style guide with logo variations, color palette, and typography.'}],
 ['FINAL DESIGNS',{type:'heading',text:'A guided app takes households from setup to everyday cooking insights.'},{type:'text',text:'I created low- and mid-fidelity wireframes for an intuitive, mostly sequential user flow. Between iterations, I incorporated client feedback and prototyped a high-fidelity design in preparation for development.'},{type:'list',items:['A guided tutorial introduces the user, then leads to a home screen for device enrollment.','After connecting an appliance, users can access payment installations, energy usage, and learning content such as tutorial videos and educational articles.','Accessibility preferences and additional resources are available from the user profile.']},{type:'image',src:'solstove/wireframes-lowfi.png',alt:'Low-fidelity wireframes for SolStove onboarding, pairing, home, energy, learning, and profile screens.'},{type:'image',src:'solstove/user-flow.png',alt:'SolStove app user flow from onboarding and sign-in through device setup and the main app sections.'},{type:'image',src:'solstove/final-screens.png',alt:'Final SolStove app screens for onboarding, device connection, payment, energy, learning, and profile.'}],
 ['PRODUCT DEMO',{type:'heading',text:'See how the app guides a household through the SolStove experience.'},{type:'prototype'}],
 ['REFLECTIONS',{type:'heading',text:'Designing for trust is as critical as designing for usability.'},{type:'text',text:'Even when solutions already exist, adoption depends on cultural alignment and perceived credibility. Building trust through clear communication, familiar patterns, and community-centered design is essential for real-world impact.'},{type:'heading',text:'Accessibility goes beyond cost—it’s also about comprehension and context.'},{type:'text',text:'Barriers that SolStove faced were financial, as well as informational and behavioral. Simplifying complex concepts and meeting users where they are enabled more inclusive and actionable experiences.'},{type:'heading',text:'Technology should empower rather than overwhelm.'},{type:'text',text:'By translating unfamiliar clean cooking technology into an intuitive, guided experience, the design supports confident decision-making and long-term adoption, demonstrating how thoughtful UX can drive meaningful social and environmental change.'}]
 ]},
 {slug:'flowstate',title:'Flowstate App',role:'Designer',desc:'Transforming long-form text into a dynamic, line-by-line reading experience.',type:'flow',facts:['Designer','4 hours','Figma Make · ClaudeAI · Supabase · Cosmos','Prompt Engineering · Rapid Prototyping · UX Research · UI Design'],skills:'Prompt Engineering · Rapid Prototyping · UX Research · UI Design',sections:[
 ['OVERVIEW',{type:'heading',text:'Background'},{type:'text',text:'Created during an AI-assisted design sprint, this project began with a central question: What intangible human experience shapes our daily lives, yet remains largely unsupported by modern technology? Working with two co-designers, we intentionally moved beyond saturated spaces like health tracking to uncover a more subtle, overlooked need. Our exploration—spanning social media’s influence on attention and behavior—ultimately led us to a core idea: the decline of sustained focus and the fading experience of long-form reading.'},{type:'heading',text:'Challenge'},{type:'text',text:'Reading is a fundamental cognitive experience, yet modern reading interfaces remain largely static—assuming all users process text at the same pace and in the same format. This creates friction for readers with varying attention spans and comprehension needs. At the same time, digital platforms have become highly adaptive, optimizing short-form content for engagement, while long-form reading lags behind. This gap raises a key question: what would it look like if reading experiences were truly adaptive, responsive, and human-centered?'},{type:'heading',text:'Opportunity'},{type:'text',text:'Today, short-form platforms have reshaped how we process information—delivering content in small, sequential chunks that reduce overload and sustain attention. Flowstate applies this principle to long-form reading, limiting visible text to improve focus, pacing, and comprehension.'},{type:'text',text:'Flowstate reimagines long-form text content and turns it into an adaptive experience. Users can browse from a built-in library, upload their own reading material, or eventually connect content from the platforms they already use. Once downloaded, Flowstate delivers the text in a digestible, customizable, and responsive format, allowing readers to control how fast or densely information is consumed.'}],
 ['PRODUCT DEMO',{type:'heading',text:'Embedded Prototype'},{type:'placeholder',text:'EMBEDDED PROTOTYPE'}],
 ['REFLECTIONS',{type:'heading',text:'Integrating Artificial Intelligence in UX/UI Design'},{type:'text',text:'This was my first AI-integrated design project in which I was iterating using Figma Make, Figma’s AI-powered prompt-to-app tool. Admittedly, it was initially considerably frustrating to translate my group’s visions into prompts; as I took on the User Experience prompting role, I took to other LLMs to support the phrasing of my inputs, which helped me better understand the depth and specificity required of prompts to produce outputs in alignment with what I had envisioned.'},{type:'heading',text:'Inspiration From Other Designers'},{type:'text',text:'While I was struggling to efficiently operate Figma Make, I researched other successful builds using the tool by referencing Figma’s featured Make-athon designs and creators’ takeaways.'}]
 ]},
 {slug:'unity-scholars-network',title:'Unity Scholars Network',role:'Website Designer',desc:'Streamlining access to free college app mentorship for 100+ underserved NYC high school students.',type:'unity',facts:['Website Designer','July 2025 (1 month)','Figma · Framer · Adobe Illustrator · Adobe Photoshop','UX Research · Interaction Design · Graphic Design · Prototyping'],skills:'UX Research · Interaction Design · Graphic Design · Prototyping',sections:[
 ['OVERVIEW',{type:'heading',text:'Background'},{type:'text',text:'Unity Scholars Network offers free college admissions mentorship for low-income high school students based in New York City. Through accessible peer mentorship, USN bridges equity gaps with holistic guidance from current undergraduate students at Top 50 universities.'},{type:'heading',text:'Challenge'},{type:'text',text:'Students from lower socioeconomic backgrounds often miss out on life-changing college opportunities—not because they’re unqualified, but because they have lack access the right resources. The existing website was reportedly difficult to navigate, proving to be a barrier to the organization’s resources and services.'},{type:'heading',text:'Opportunity'},{type:'text',text:'Design a revamped website that emphasizes streamlined navigation and caters to high school students to aid the organization’s humanitarian mission.'},{type:'text',text:'By redesigning Unity Scholars Network’s website with an emphasis on clarity, accessibility, and storytelling, the new design highlights the organization’s mission through strong visuals, streamlined navigation, and condensed content.'}],
 ['PROCESS',{type:'heading',text:'Project Process'},{type:'text',text:'1. Research — Identifying Problems · Desk Research · Interviews'},{type:'text',text:'2. Synthesis — Pain Points · User Persona · User Needs'},{type:'text',text:'3. Ideation — Moodboard · Style Guide · Low-Fidelity'},{type:'text',text:'4. Final Designs — High-Fidelity · Prototyping · User Testing'},{type:'text',text:'5. Reflections — Further Explorations'}],
 ['RESEARCH',{type:'heading',text:'User Research'},{type:'text',text:'Stakeholder interviews with the CEO, program coordinators, mentors, and high school students to directly gauge organizational goals, values, and internal challenges with engagement.'},{type:'text',text:'Competitive analysis of other mentorship and student-based nonprofit websites to evaluate standardized features of consultation services, content hierarchy of persuasive information, and system flows with appealing interactions.'},{type:'heading',text:'Synthesis'},{type:'text',text:'Stakeholder interviews helped identify pain points with the old site, narrowing down three target issues:'},{type:'text',text:'1. Lack of visual appeal hindered motivations for prolonged engagement.'},{type:'text',text:'2. Unclear program benefits and structural information.'},{type:'text',text:'3. Difficulties navigating forms like applications and donor platforms.'},{type:'text',text:'My takeaways were as follows:'},{type:'text',text:'1. Establish a suitable style guide and ensure consistency across the website’s visual elements to enhance appeal, maintain engagement, and improve perceived user experience.'},{type:'text',text:'2. Re-evaluate the content hierarchy and revise text to highlight key points in a concise, yet informative manner, clarifying program benefits.'},{type:'text',text:'3. Replace the existing interest form with an embedded application form to streamline form navigation.'}],
 ['IDEATING',{type:'heading',text:'Ideation'},{type:'text',text:'After evaluating the existing website, I identified the updated content structure using a user flow diagram and began wireframing the hierarchy for each page. This layout aimed to prioritize the organization’s key points and seamlessly direct users to their desired pages.'}],
 ['FINAL DESIGNS',{type:'heading',text:'Final Designs'},{type:'text',text:'The final prototype consistently utilizes a renewed brand identity that is adequately designed for a younger audience. Adding stock images, regularly enforcing a vibrant accent color, and incorporating movement design via card carousels increases visual interest and provides engaging user interaction. Additionally, each page is restructured to improve content hierarchy, distributing the density of content based on category and key points. This layout improves user navigation and clarifies vital information for efficient intake.'}],
 ['PRODUCT DEMO',{type:'heading',text:'VIDEO DEMO'},{type:'placeholder',text:'VIDEO DEMO'},{type:'heading',text:'Interactive Prototype'},{type:'text',text:'unityscholars.com/'}],
 ['REFLECTIONS',{type:'heading',text:'My Foot in the Door of Practical Design'},{type:'text',text:'Unity Scholars Network was my first full-scale project on Framer, which proved to be an incredibly steep yet gratifying learning curve. I independently taught myself how to use Framer in tandem with Figma, experimenting with different tools and workflows until I felt confident in creating an interactive, functional design. This process not only strengthened my adaptability but also pushed me to grow technically, professionally, and creatively as a designer.'},{type:'heading',text:'Rebranding from Scratch'},{type:'text',text:'Rebranding an existing identity presented a unique creative challenge. Rather than starting from scratch, I worked to refine and expand on the CEO’s vision, ensuring the visual identity reflected the organization’s mission while staying scalable for growth. This taught me how to balance creative input with respect for an existing brand’s direction and values.'},{type:'heading',text:'Working within a Network'},{type:'text',text:'Collaborating with a newer, fast-growing nonprofit organization was beyond insightful in ways I hadn’t anticipated. Because the executive team was still shaping its operations, I had the opportunity to interact with multiple departments, receive an abundance of constructive feedback, and understand the evolving needs of a young nonprofit. This cross-team collaboration broadened my perspective, showing me how design decisions impact every operational level of an organization, from program staff to mentors to prospective members.'},{type:'heading',text:'Going Forward'},{type:'text',text:'I hope to continue working with this organization to improve the website’s user experience and adapt its interface as its program expands in size, needs, and operations. Going forward, I would like to conduct more research to better understand the needs of the organization’s high school applicants. Over a longer span of time, I aim to create a platform within the website to streamline the application process and information retrieval systems rather than rely on third-party forms and documents.'}]
 ]},
 {slug:'woods-and-shrubs',title:'Woods & Shrubs',role:'Graphic Designer',desc:'Revamping herbal cosmetics product design and cultural brand identity.',type:'woods',facts:['Graphic Designer','June 2025 - July 2025 (2 months)','Adobe Illustrator · Adobe Photoshop · Adobe Lightroom · Figma','Graphic Design · Branding · Market Research · Project Management'],skills:'Graphic Design · Branding · Market Research · Project Management',sections:[
 ['OVERVIEW',{type:'heading',text:'Background'},{type:'text',text:'Woods & Shrubs is a family-owned herbal cosmetics company rooted in generations of knowledge, practice, and reverence for nature. Originally launched in a modest mom-and-pop shop in South Asia, Woods & Shrubs now enters the international stage, offering a new identity that honors its roots while bringing ancestral herbal wisdom to consumers across the U.S.'},{type:'heading',text:'Challenge'},{type:'text',text:'Position an international mom-and-pop shop for successful entry and growth in the Western cosmetics market via creative redirection.'},{type:'text',text:'Despite having a loyal customer base in South Asia, Woods & Shrubs lacks visibility and brand recognition in the U.S. market. Expanding internationally requires more than just introducing products—it means building trust, communicating cultural significance authentically, and crafting a brand identity that would resonate with a new, diverse consumer base while maintaining the integrity of heritage.'},{type:'heading',text:'Opportunity'},{type:'text',text:'Design a modern brand identity that proudly embraces heritage and will be applied to the company’s premier product and digital presence.'},{type:'text',text:'Firstly, I established a solid style guide adequately reflecting the sentiment behind the company. I conducted interviews with the company CEO to compose an authentic background behind his mission and values. This style guide includes a new logo with various logotypes, a consistent color palette, and typography system that evoke natural earth tones and textures, symbolizing both tradition and sustainability. After receiving approval for the style guide, I researched various minimalist, eco-conscious packaging designs that highlight transparency (ingredients, sourcing) while maintaining a premium aesthetic. Packaging architecture and label designs were also considered in this process to distinguish the product from that of competitors. To produce promotional infographics, I used these various visual elements in tandem with the founder’s cultural narratives. By highlighting generational knowledge, sourcing origins, and the company’s environmental commitments, I aimed to execute a brand identity that celebrates ancestral knowledge while maintaining a modern, luxurious feel for potential customers.'}],
 ['PROCESS',{type:'heading',text:'Project Process'},{type:'text',text:'1. Research — Identifying Problems · Desk Research · Interviews'},{type:'text',text:'2. Synthesis — Pain Points · User Persona · User Needs'},{type:'text',text:'3. Ideation — Moodboard · Style Guide · Iterations'},{type:'text',text:'4. Final Designs — Digital Mockups · Prototyping · Deliverables'},{type:'text',text:'5. Reflections — Further Explorations'}],
 ['RESEARCH',{type:'heading',text:'User Research'},{type:'text',text:'Conducted market analysis on U.S. herbal and clean beauty markets, identifying trends in natural skincare, consumer demand for authenticity, and the rising influence of wellness-focused branding.'},{type:'text',text:'Competitively reviewed existing “natural brands” to identify gaps in brand storytelling, packaging, and online presence.'},{type:'text',text:'Explored how heritage-based beauty brands balance authenticity with modern aesthetics when entering Western markets.'},{type:'heading',text:'Synthesis'},{type:'heading',text:'Research Takeaways'},{type:'text',text:'U.S. consumers are drawn to natural skincare brands that have authentic cultural roots and transparent ingredient sourcing.'},{type:'text',text:'While storytelling adds sentiment and credibility, visual branding and packaging must appeal to global standards of design and usability.'},{type:'text',text:'Ingredient clarity, sustainability practices, and storytelling about South Asian hair-oiling practices are critical in building trust with first-time U.S. buyers.'},{type:'text',text:'With no established storefront presence in the U.S., Woods & Shrubs’ entry must prioritize a digital-first strategy—website, social media, and e-commerce outlets.'},{type:'text',text:'To reimagine Woods and Shrubs’ brand identity while incorporating these takeaways, I researched South Asian art to inform the visual direction—drawing from its color palettes, motifs, and techniques. As a result, I approached the company’s aesthetic by blending traditional richness with a contemporary style when visualizing the brand identity and first label design.'}],
 ['IDEATING',{type:'heading',text:'Ideation'},{type:'text',text:'After meeting with the client, I received and implemented the following pieces of feedback:'},{type:'text',text:'1. The manufacturer suggested a minimalistic label and packaging style given the product’s novelty as the company’s first launch. A colorful style could be saved for limited edition campaigns.'},{type:'text',text:'2. A key aspect behind this product’s success in the marketplace should be its appeal to college students as well as a differentiating feature.'},{type:'text',text:'To approach these points, I translated the main themes of my previous design—South Asian-inspired embellishments, color palettes, font qualities—into a minimalistic style, designing three iterations to be considered by the client. To make Woods and Shrubs’ herbal hair oil into a particularly attention-catching and unique hair oil product for college students, I took to a foldable box architecture design that was externally minimalistic and would be flattened upon unraveling the box to reveal information in a visually interesting way. The internal surface outlined South Asian hair oiling instructions while transparently informing users of the product’s ingredients and simplifying its respective individual purposes. These key design features not only produced a comprehensive bottle label and packaging container but also an immersive experience for consumers to become well educated in the natural and cultural essence of the product.'}],
 ['FINAL DESIGNS',{type:'heading',text:'Final Designs'},{type:'text',text:'The second iteration—encompassing an iteration of the secondary logo, a simplistic accent logo and product description, and border embellishments—was selected as the final design.'}],
 ['PRODUCT DEMO',{type:'heading',text:'VIDEO DEMO'},{type:'placeholder',text:'VIDEO DEMO'}],
 ['REFLECTIONS',{type:'heading',text:'You don’t have to reject modernity, you can integrate it into tradition.'},{type:'text',text:'This project challenged me to think critically about how cultural heritage can be translated into modern branding without diluting its authenticity. I spent a decent amount of time researching South Asian design and attempting to integrate its various aspects, including color, artistic styles, etc. to ensure the brand honors its roots while appealing to new audiences.'},{type:'heading',text:'Aesthetics build a feeling.'},{type:'text',text:'Woods & Shrubs has deepened my understanding that brand storytelling is a much stronger strategic tool than many may anticipate. While researching larger companies within the natural cosmetic field, I found that many utilized visuals, language, and feel to establish their brand rather than relying on product photography. Aesthetics play a major role in establishing one’s place within a competitive market. Good design, however, is not only consistent aesthetics—it should bridge and create a community of shared experience.'},{type:'heading',text:'Where there lacked collaboration, my autonomy filled the gap.'},{type:'text',text:'Meeting weekly with the founder was incredibly valuable to my learning experience as a mentee. Despite the initial ambiguity of my mentorship, I was given immense liberty both creatively and organizationally. I exercised independent direction, taking ownership of design decisions and bringing my own perspective to the project. This balance between collaboration and autonomy gave me confidence in both my creative instincts and my ability to communicate them effectively. Additionally, I gained insight into the vision and values driving the company, while also practicing how to present deliverables clearly and persuasively.'},{type:'heading',text:'Going forward'},{type:'text',text:'As Woods & Shrubs continues to establish its presence in the U.S., I hope to remain involved in supporting the brand’s growth as the founder’s story resonated strongly with my own as a second-generation immigrant. My goal is to strengthen the company’s digital presence by helping develop and design its website, optimizing e-commerce functionality, and building a cohesive social media strategy that highlights both products and cultural storytelling.'}]
 ]},
];
const nav=(active='')=>`<div class="nav-wrap ${active==='home'?'home-nav':''}"><nav class="nav"><a class="${active==='home'?'active':''}" href="${base}">Work</a><a class="${active==='play'?'active':''}" href="${base}playground/">Play</a><a class="${active==='about'?'active':''}" href="${base}about/">About</a></nav></div>`;
const setNavSection=(section,target=document)=>{const nav=target.querySelector('.nav');if(!nav)return;nav.querySelectorAll('a').forEach(link=>link.classList.toggle('active',link.textContent.trim().toLowerCase().includes(section)))};
const animateBioText=(element,text)=>{if(!element||element.dataset.bioText===text)return;element.dataset.bioText=text;const doc=element.ownerDocument,view=doc.defaultView,style=view.getComputedStyle(element),canvas=doc.createElement('canvas'),ctx=canvas.getContext('2d'),maxWidth=element.clientWidth,letterSpacing=parseFloat(style.letterSpacing)||0;ctx.font=`${style.fontStyle} ${style.fontVariant} ${style.fontWeight} ${style.fontSize} ${style.fontFamily}`;const lines=[];let line='';for(const word of text.trim().split(/\s+/)){const candidate=line?`${line} ${word}`:word;const width=ctx.measureText(candidate).width+Math.max(0,candidate.length-1)*letterSpacing;if(line&&maxWidth&&width>maxWidth){lines.push(line);line=word}else line=candidate}if(line)lines.push(line);element.classList.remove('bio-animating');element.replaceChildren(...lines.map((lineText,index)=>{const span=doc.createElement('span');span.className='bio-line';span.style.setProperty('--line-index',index);span.textContent=lineText;return span}));void element.offsetWidth;element.classList.add('bio-animating')};
const sideOverview=(playPage=false,aboutPage=false)=>`<aside class="home-overview"><div class="home-signature"><img class="signature-photo" src="${base}assets/media/karen-profile.jpg?v=20261013-profile-photo2" alt="" data-lightbox-caption="Hi :D"><div><strong>Karen L.</strong> <span id="home-role">Product Designer</span></div></div>${aboutPage?'<p class="bio-copy">Why UX Design, you may ask?</p>':`<p class="bio-copy${playPage?' play-bio':''}">${playPage?'Before I studied UX/UI to design experiences, I was a fine arts major in love with capturing them. Photography has undoubtedly shaped my design instinct and still guides how I design for people today.':'I create digital products that thoughtfully tackle everyday challenges to make people’s lives easier.'}</p>`}</aside>`;
const sideWeather=()=>`<aside class="home-weather" aria-label="New York local time and weather"><strong>New York, NY</strong><span id="ny-time">Loading local time…</span><span id="ny-weather">Getting current weather…</span></aside>`;
function startSideInfo(){const role=document.getElementById('home-role');if(role&&!window.matchMedia('(prefers-reduced-motion: reduce)').matches){const roles=['Product Designer','Artist','New Yorker','Chinese-American','Photojournalist','Spice Enthusiast'];let index=0,deleting=false;const tick=()=>{const word=roles[index],current=role.textContent;role.textContent=deleting?current.slice(0,-1):word.slice(0,current.length+1);let delay=deleting?42:76;if(!deleting&&role.textContent===word){deleting=true;delay=1250}else if(deleting&&role.textContent===''){deleting=false;index=(index+1)%roles.length;delay=280}setTimeout(tick,delay)};setTimeout(()=>{deleting=true;tick()},1500)}const time=document.getElementById('ny-time');if(time){const updateTime=()=>{time.textContent=new Intl.DateTimeFormat('en-US',{timeZone:'America/New_York',hour:'numeric',minute:'2-digit'}).format(new Date())};updateTime();setInterval(updateTime,30000)}const weather=document.getElementById('ny-weather');if(weather)fetch('https://api.open-meteo.com/v1/forecast?latitude=40.7128&longitude=-74.0060&current=temperature_2m,weather_code&temperature_unit=fahrenheit&timezone=America%2FNew_York').then(r=>{if(!r.ok)throw new Error('weather unavailable');return r.json()}).then(data=>{const labels={0:'Clear',1:'Mostly clear',2:'Partly cloudy',3:'Cloudy',45:'Foggy',48:'Foggy',51:'Light drizzle',53:'Drizzle',55:'Heavy drizzle',61:'Light rain',63:'Rain',65:'Heavy rain',71:'Light snow',73:'Snow',75:'Heavy snow',80:'Showers',81:'Showers',82:'Heavy showers',95:'Thunderstorms'};weather.textContent=`${labels[data.current.weather_code]||'Current conditions'} · ${Math.round(data.current.temperature_2m)}°F`}).catch(()=>{weather.textContent='Weather unavailable'})}
const footer=()=>`<footer class="connect-footer"><div class="connect-footer-inner"><div class="connect"><div class="tiny">THANKS FOR THE SCROLL :)</div><h2>Let’s connect!</h2><div class="socials"><a href="https://linkedin.com/in/2024klin/" target="_blank" rel="noreferrer">LinkedIn ↗</a><a href="mailto:linkaren@umich.edu">Email ↗</a><a href="https://instagram.com/kameraofkaren/" target="_blank" rel="noreferrer">Instagram ↗</a></div></div><a class="back-to-top" href="#top">Go back up ↑</a></div></footer>`;
const root=document.getElementById('app');const path=decodeURI(location.pathname).replace(/\/index\.html$/,'').replace(/\/$/,'');const nested=/\/(about|playground|craft|proj-flush|michigan-advertising-marketing|maizebus|snuffed|solstove|flowstate|unity-scholars-network|woods-and-shrubs)$/.test(path);const transitionPreview=new URLSearchParams(location.search).has('transition');const deep=/\/playground\/(craft|proj-flush)$/.test(path);const base=deep?'../../':nested?'../':'./';

function installEndTransition(nextUrl){if(!transitionPreview&&!window.matchMedia('(min-width:701px) and (min-height:650px)').matches)return;const sectionMode=transitionPreview,nextScreen=document.querySelector('.play-next-screen');let pushed=0,effort=0,resetTimer=null,changing=false;const atEnd=()=>document.scrollingElement.scrollTop+window.innerHeight>=document.scrollingElement.scrollHeight-2;const resetEffort=()=>{effort=0;clearTimeout(resetTimer)};const activate=active=>{if(nextScreen)nextScreen.style.pointerEvents=active?'auto':'none';document.body.classList.toggle('about-section-active',active);if(sectionMode){try{window.top.document.body.classList.toggle('play-section-active',!active)}catch(_){}}};const update=value=>{pushed=Math.max(0,Math.min(window.innerHeight,value));document.documentElement.style.setProperty('--page-push',`${-pushed}px`);if(sectionMode){const aboutActive=pushed>=window.innerHeight*.5;try{const topDoc=window.top.document;setNavSection(aboutActive?'about':'play',topDoc);const bio=topDoc.querySelector('.home-overview .bio-copy');if(bio){animateBioText(bio,aboutActive?'Why UX Design, you may ask?':'Before I studied UX/UI to design experiences, I was a fine arts major in love with capturing them. Photography has undoubtedly shaped my design instinct and still guides how I design for people today.');bio.classList.toggle('play-bio',!aboutActive)}}catch(_){}activate(pushed>=window.innerHeight*.98)}else if(pushed>=window.innerHeight*.98&&!changing){changing=true;setTimeout(()=>location.href=nextUrl,220)}};const push=distance=>{const step=distance;if(effort<120){effort+=step;const released=Math.max(0,effort-120);if(effort>=120)effort=120;if(released)update(pushed+released*.8);clearTimeout(resetTimer);resetTimer=setTimeout(resetEffort,1400);return}update(pushed+step*.8)};document.addEventListener('wheel',event=>{if(event.deltaY<0&&pushed>0){event.preventDefault();event.stopPropagation();resetEffort();update(pushed+event.deltaY*.65);return}if(event.deltaY<0)resetEffort();if(event.deltaY>0&&atEnd()){event.preventDefault();push(event.deltaY)}},{passive:false});let touchY=null;document.addEventListener('touchstart',event=>{touchY=event.touches[0].clientY},{passive:true});document.addEventListener('touchmove',event=>{if(touchY===null)return;const y=event.touches[0].clientY,delta=touchY-y;if(delta<0&&pushed>0){event.preventDefault();resetEffort();update(pushed+delta*.65)}else if(delta<0)resetEffort();else if(delta>0&&atEnd()){event.preventDefault();push(delta)}touchY=y},{passive:false});document.addEventListener('touchend',()=>{touchY=null},{passive:true});if(sectionMode&&nextScreen)nextScreen.addEventListener('load',()=>{const frameDoc=nextScreen.contentDocument,frameRoot=frameDoc.scrollingElement;frameDoc.addEventListener('wheel',event=>{if(event.deltaY<0&&frameRoot.scrollTop<=2&&pushed>0){event.preventDefault();event.stopPropagation();update(pushed+event.deltaY*.65)}},{passive:false,capture:true});let frameTouchY=null;frameDoc.addEventListener('touchstart',event=>{frameTouchY=event.touches[0].clientY},{passive:true});frameDoc.addEventListener('touchmove',event=>{if(frameTouchY===null)return;const y=event.touches[0].clientY,delta=frameTouchY-y;if(delta<0&&frameRoot.scrollTop<=2&&pushed>0){event.preventDefault();event.stopPropagation();update(pushed+delta*.65)}frameTouchY=y},{passive:false,capture:true})})}

function createMaizeVideoMatte(video,cover){
 if(!video||!cover)return null;
 video.playbackRate=1.68;
 const canvas=document.createElement('canvas');canvas.className='maizebus-cover-keyed';canvas.setAttribute('aria-hidden','true');cover.append(canvas);
 const context=canvas.getContext('2d',{willReadFrequently:true});if(!context)return null;
 let frameId=0,width=0,height=0,seen,queue;
 const draw=(force=false)=>{
  frameId=0;if((video.paused&&!force)||video.ended||video.readyState<2||!video.videoWidth)return;
  try{
   const scale=Math.min(1,2400/video.videoWidth,2400/video.videoHeight),nextWidth=Math.max(1,Math.round(video.videoWidth*scale)),nextHeight=Math.max(1,Math.round(video.videoHeight*scale));
   if(nextWidth!==width||nextHeight!==height){width=canvas.width=nextWidth;height=canvas.height=nextHeight;seen=new Uint8Array(width*height);queue=new Int32Array(width*height)}
   context.drawImage(video,0,0,width,height);const frame=context.getImageData(0,0,width,height),pixels=frame.data,bg=[pixels[0],pixels[1],pixels[2]];seen.fill(0);let head=0,tail=0;
   const enqueue=index=>{if(index<0||index>=width*height||seen[index])return;const offset=index*4,dr=pixels[offset]-bg[0],dg=pixels[offset+1]-bg[1],db=pixels[offset+2]-bg[2];if(dr*dr+dg*dg+db*db>3600)return;seen[index]=1;queue[tail++]=index};
   for(let x=0;x<width;x++){enqueue(x);enqueue((height-1)*width+x)}for(let y=0;y<height;y++){enqueue(y*width);enqueue(y*width+width-1)}
   while(head<tail){const index=queue[head++],offset=index*4,x=index%width,y=(index/width)|0;pixels[offset+3]=0;if(x>0)enqueue(index-1);if(x<width-1)enqueue(index+1);if(y>0)enqueue(index-width);if(y<height-1)enqueue(index+width)}
   context.putImageData(frame,0,0);cover.classList.add('has-keyed-maize-video');if(!video.paused)frameId=requestAnimationFrame(draw);
  }catch(_){cover.classList.remove('has-keyed-maize-video')}
 };
 const start=()=>{if(!frameId)frameId=requestAnimationFrame(draw)},stop=()=>{if(frameId)cancelAnimationFrame(frameId);frameId=0};
 video.addEventListener('play',start);video.addEventListener('pause',stop);video.addEventListener('ended',stop);video.addEventListener('loadeddata',()=>draw(true));video.addEventListener('seeked',()=>draw(true));return canvas;
}
function home(){const featured=projects.filter(p=>!['flowstate','unity-scholars-network','woods-and-shrubs','solstove'].includes(p.slug)).sort((a,b)=>a.slug==='maizebus'?-1:b.slug==='maizebus'?1:0);const cards=featured.map(p=>{const tags=Array.isArray(projectKinds[p.slug])?projectKinds[p.slug]:[projectKinds[p.slug]||'Personal Project'];return `<a class="card" href="${base}${p.slug}/"><div class="cover ${p.type}" style="view-transition-name:case-cover-${p.slug}">${p.slug==='michigan-advertising-marketing'?`<img class="mam-cover-image" src="${base}assets/media/mam-site-cover.jpg" alt="" loading="eager"><video class="mam-cover-video" muted playsinline preload="none" poster="${base}assets/media/mam-site-cover.jpg" aria-hidden="true"><source src="${base}assets/media/mam-site-loop.mp4" type="video/mp4"></video>`:''}${p.slug==='solstove'?`<img class="solstove-cover-image" src="${base}assets/media/solstove/cover-app-collage.png" alt="" loading="eager">`:''}${p.slug==='maizebus'?`<video class="maizebus-cover-video" muted playsinline loop preload="metadata" aria-hidden="true"><source src="${base}assets/media/maizebus-landing-cover.mp4?v=20261001-2" type="video/mp4"></video><img class="maizebus-cover-poster" alt="" aria-hidden="true">`:''}${p.slug==='snuffed'?`<img class="snuffed-home-cover-image" src="${base}assets/media/snuffed-cover.jpg?v=20261010-snuffed-cover-home1" alt="" loading="eager">`:''}<span class="mark">${p.type==='maize'?'M':p.type==='mam'?'MAM':p.type==='sol'?'SOL':''}</span><span class="label">${p.title}</span></div><div class="card-copy"><div class="meta">${['maizebus','michigan-advertising-marketing','snuffed','solstove'].includes(p.slug)?'':p.title}</div><h2>${p.desc}</h2><div class="project-tags">${tags.map(tag=>`<span class="project-tag">${tag}</span>`).join('')}</div></div></a>`}).join('');root.innerHTML=`${nav('home')}${sideOverview()}${sideWeather()}<main id="top" class="home-main"><section class="projects home-projects" aria-label="Selected work">${cards}</section></main>`;
 const mamVideo=document.querySelector('.home-projects .mam-cover-video'),mamCard=mamVideo?.closest('.card');const playMam=()=>{if(!mamVideo)return;if(mamVideo.currentTime<1)mamVideo.currentTime=1;mamVideo.play().catch(()=>{})};const stopMam=()=>{if(mamVideo){mamVideo.pause();mamVideo.currentTime=0}};mamCard?.addEventListener('pointerenter',event=>{if(event.pointerType!=='touch')playMam()});mamCard?.addEventListener('pointerleave',stopMam);mamCard?.addEventListener('focusin',playMam);mamCard?.addEventListener('focusout',event=>{if(!mamCard.contains(event.relatedTarget))stopMam()});const maizeVideo=document.querySelector('.home-projects .maizebus-cover-video'),maizeCard=maizeVideo?.closest('.card'),maizePoster=maizeCard?.querySelector('.maizebus-cover-poster');const maizePosterTime=.5;createMaizeVideoMatte(maizeVideo,maizeCard?.querySelector('.cover.maize'));const playMaize=()=>{if(maizeVideo)maizeVideo.play().catch(()=>{})};const stopMaize=()=>{if(maizeVideo){maizeVideo.pause();maizeVideo.currentTime=maizePosterTime}};maizeCard?.addEventListener('pointerenter',event=>{if(event.pointerType!=='touch')playMaize()});maizeCard?.addEventListener('pointerleave',stopMaize);maizeCard?.addEventListener('focusin',playMaize);maizeCard?.addEventListener('focusout',event=>{if(!maizeCard.contains(event.relatedTarget))stopMaize()});const captureMaizePoster=()=>{if(!maizeVideo?.videoWidth||!maizePoster||maizePoster.dataset.ready||Math.abs(maizeVideo.currentTime-maizePosterTime)>.08)return;try{const canvas=document.createElement('canvas');canvas.width=maizeVideo.videoWidth;canvas.height=maizeVideo.videoHeight;const context=canvas.getContext('2d',{willReadFrequently:true});context.drawImage(maizeVideo,0,0);const frame=context.getImageData(0,0,canvas.width,canvas.height);const pixels=frame.data,width=canvas.width,height=canvas.height,bg=[pixels[0],pixels[1],pixels[2]],seen=new Uint8Array(width*height),queue=new Int32Array(width*height);let head=0,tail=0;const enqueue=index=>{if(seen[index])return;const offset=index*4,dr=pixels[offset]-bg[0],dg=pixels[offset+1]-bg[1],db=pixels[offset+2]-bg[2];if(dr*dr+dg*dg+db*db>3600)return;seen[index]=1;queue[tail++]=index};for(let x=0;x<width;x++){enqueue(x);enqueue((height-1)*width+x)}for(let y=0;y<height;y++){enqueue(y*width);enqueue(y*width+width-1)}while(head<tail){const index=queue[head++],offset=index*4,x=index%width,y=(index/width)|0;pixels[offset+3]=0;if(x>0)enqueue(index-1);if(x<width-1)enqueue(index+1);if(y>0)enqueue(index-width);if(y<height-1)enqueue(index+width)}context.putImageData(frame,0,0);maizePoster.src=canvas.toDataURL('image/png');maizePoster.dataset.ready='true'}catch(_){}};maizeVideo?.addEventListener('loadedmetadata',()=>{maizeVideo.currentTime=maizePosterTime});maizeVideo?.addEventListener('seeked',captureMaizePoster);
 const role=document.getElementById('home-role');if(role&&!window.matchMedia('(prefers-reduced-motion: reduce)').matches){const roles=['Product Designer','Artist','New Yorker','Chinese-American','Photojournalist','Spice Enthusiast'];let index=0,deleting=false;const tick=()=>{const word=roles[index],current=role.textContent;role.textContent=deleting?current.slice(0,-1):word.slice(0,current.length+1);let delay=deleting?42:76;if(!deleting&&role.textContent===word){deleting=true;delay=1250}else if(deleting&&role.textContent===''){deleting=false;index=(index+1)%roles.length;delay=280}setTimeout(tick,delay)};setTimeout(()=>{deleting=true;tick()},1500)}
 const projectList=document.querySelector('.home-projects');let touchY=null,touchOutsideProjects=false;const scrollProjects=delta=>{projectList.scrollTop+=delta};document.addEventListener('wheel',event=>{if(!event.target.closest('.home-projects')){event.preventDefault();scrollProjects(event.deltaY)}},{passive:false});document.addEventListener('touchstart',event=>{touchY=event.touches[0].clientY;touchOutsideProjects=!event.target.closest?.('.home-projects')},{passive:true});document.addEventListener('touchmove',event=>{if(touchY===null)return;const nextY=event.touches[0].clientY,delta=touchY-nextY;if(touchOutsideProjects){event.preventDefault();scrollProjects(delta)}touchY=nextY},{passive:false});document.addEventListener('touchend',()=>{touchY=null;touchOutsideProjects=false},{passive:true});
 const time=document.getElementById('ny-time');const updateTime=()=>{time.textContent=new Intl.DateTimeFormat('en-US',{timeZone:'America/New_York',hour:'numeric',minute:'2-digit'}).format(new Date())};updateTime();setInterval(updateTime,30000);
 const weather=document.getElementById('ny-weather');fetch('https://api.open-meteo.com/v1/forecast?latitude=40.7128&longitude=-74.0060&current=temperature_2m,weather_code&temperature_unit=fahrenheit&timezone=America%2FNew_York').then(r=>{if(!r.ok)throw new Error('weather unavailable');return r.json()}).then(data=>{const labels={0:'Clear',1:'Mostly clear',2:'Partly cloudy',3:'Cloudy',45:'Foggy',48:'Foggy',51:'Light drizzle',53:'Drizzle',55:'Heavy drizzle',61:'Light rain',63:'Rain',65:'Heavy rain',71:'Light snow',73:'Snow',75:'Heavy snow',80:'Showers',81:'Showers',82:'Heavy showers',95:'Thunderstorms'};weather.textContent=`${labels[data.current.weather_code]||'Current conditions'} · ${Math.round(data.current.temperature_2m)}°F`}).catch(()=>{weather.textContent='Weather unavailable'});
}
function processGallery(prefix,showOverview){const tabs=[['raw','Raw Vibecode'],['iterations','Iterations'],['final','Final'],['overview','Overview']];return `<div class="process-gallery"><div class="process-tabs" role="tablist" aria-label="MAM design process stages">${tabs.map(([key,label],index)=>`<button type="button" role="tab" id="${prefix}-tab-${key}" aria-selected="${key==='overview'}" aria-controls="${prefix}-panel-${key}" tabindex="${key==='overview'?0:-1}" data-process-tab="${key}">${label}</button>`).join('')}</div>${tabs.map(([key,label],index)=>`<div class="process-tab-panel" role="tabpanel" id="${prefix}-panel-${key}" aria-labelledby="${prefix}-tab-${key}" data-process-panel="${key}" ${key==='overview'?'':'hidden'}>${showOverview&&key==='overview'?`<figure class="process-figure"><img src="${base}assets/media/mam-dashboard-overview.png" alt="Recruitment dashboard concepts and wireframes arranged on a pink design board" loading="lazy"><figcaption>Here's how I organized the iteration and revision process for the recruitment dashboard aspect of my manual design file!</figcaption></figure>`:prefix==='mam-dashboard'&&key==='iterations'?`<figure class="process-figure"><img src="${base}assets/media/mam-dashboard-iterations.png" alt="Recruitment dashboard iterations showing applicant cards, reviewer notes, scoring rubric, and applicant profiles" loading="lazy"><figcaption>I wireframed my iterations on Figma to provide my LLMs with better references. Providing visual input often made it easier to communicate desired feature interfaces (and how they functioned at different states).</figcaption></figure>`:prefix==='mam-dashboard'&&key==='final'?`<figure class="process-figure"><img src="${base}assets/media/mam-dashboard-final.png" alt="Final recruitment dashboard with decision-stage applicants, scoring rubric, evaluation form, and reviewer ratings" loading="lazy"><figcaption>Since the dashboard is internally-facing, I unfortunately cannot embed the shipped product. However, I've provided some snapshots of the experience for reviewing applicants, scoring candidates, recording evaluations, and advancing decisions.</figcaption></figure>`:prefix==='mam-dashboard'&&key==='raw'?`<figure class="process-figure"><img src="${base}assets/media/mam-dashboard-raw-vibecode.png" alt="Early MAM recruitment dashboard vibecode with the applications view, applicant detail and notes modal, and recruitment decision dashboard" loading="lazy"><figcaption><p>My first few prompts to Lovable produced prototypes with everything I asked for, like phase tabs, expanded overlays and comment fields. However, the layouts were dense, and features the team used often took extra steps to reach.</p><p>For example, we ask applicants for headshots so we can put a face to a name and remember our interactions with them. Lovable shrank the headshots to small circles beside each name, and you had to click one to see it full size.</p><p>It was a minor yet significant point of friction, and details like this, which depend on how people actually behave, took deliberate reworking.</p></figcaption></figure>`:prefix==='mam-website'&&key==='overview'?`<figure class="process-figure"><img src="${base}assets/media/mam-website-overview.png" alt="MAM website redesign boards showing the original vibecoded site and reworked designs" loading="lazy"><figcaption>Website redesign overview: the original vibecoded site alongside refined page layouts and visual directions.</figcaption></figure>`:prefix==='mam-website'&&key==='raw'?`<figure class="process-figure"><img src="${base}assets/media/mam-website-raw-vibecode.png" alt="Early vibecoded Michigan Advertising and Marketing website concepts, including the home page, organization overview, and client pages" loading="lazy"><figcaption><p>The beginning stages of the website redesign consisted of migrating the existing website, which was created using Squarespace and last updated in 2021.</p><p>While the raw vibecoded output sufficiently translated the content from the Home, About, and Client/Team pages, the information was dense, outdated, and difficult to follow.</p></figcaption></figure>`:prefix==='mam-website'&&key==='final'?`<figure class="process-figure process-embed-figure"><div class="process-laptop"><div class="process-laptop-screen"><iframe class="process-site-embed" src="https://umichmam.org/" title="Michigan Advertising &amp; Marketing live website" loading="lazy"></iframe></div><img class="process-laptop-frame" src="${base}assets/media/mam-laptop-frame.png" alt="" aria-hidden="true"></div><figcaption>Live Michigan Advertising &amp; Marketing website. <a href="https://umichmam.org/" target="_blank" rel="noopener">Open site in a new tab ↗</a></figcaption></figure>`:prefix==='mam-website'&&key==='iterations'?`<figure class="process-figure"><img src="${base}assets/media/mam-website-iterations.png" alt="Website redesign iterations showing Michigan Advertising and Marketing page layouts and visual refinements" loading="lazy"><figcaption><p>To accurately convey my organization's desired brand identity and website functionality, I manually created a couple high-fidelity iterations across page layouts and visual refinements.</p><p>I used these as input references for my LLM to recreate.</p></figcaption></figure>`:`<div class="media-placeholder process-tab-placeholder"><span>${label.toUpperCase()}</span></div>`}</div>`).join('')}</div>`}
function mamProcessGroups(){return `<div class="process-groups"><section class="process-group"><h3 class="process-group-title">Recruitment Dashboard</h3>${processGallery('mam-dashboard',true)}</section><section class="process-group"><h3 class="process-group-title">Website Redesign</h3>${processGallery('mam-website',false)}</section></div>`}
function setupMamProcessStory(section){
 const groups=[...section.querySelectorAll('.process-group')];
 if(!groups.length)return;
 const stories=[];
 let stepIndex=0;
 groups.forEach(group=>{
  const groupTitle=group.querySelector('.process-group-title')?.textContent.trim()||'';
  const gallery=group.querySelector('.process-gallery');
  const tabs=[...(gallery?.querySelectorAll('[role="tab"]')||[])];
  const story=document.createElement('div');
  story.className='mam-process-story';
  const copy=document.createElement('div');
  copy.className='mam-process-copy';
  const groupLabel=document.createElement('span');
  groupLabel.className='mam-process-group-label';
  groupLabel.textContent=groupTitle;
  const list=document.createElement('div');
  list.className='mam-process-list';
  const stage=document.createElement('div');
  stage.className='mam-process-stage';
  const triggers=document.createElement('div');
  triggers.className='mam-process-triggers';
  triggers.setAttribute('aria-hidden','true');
  tabs.forEach(tab=>{
   const panel=gallery.querySelector(`[data-process-panel="${tab.dataset.processTab}"]`);
   if(!panel)return;
   const captionElement=panel.querySelector('figcaption');
   const captions=captionElement?.querySelectorAll(':scope > p').length
    ? [...captionElement.querySelectorAll(':scope > p')].map(paragraph=>paragraph.textContent.trim())
    : [captionElement?.textContent.trim()||''];
   const visual=panel.querySelector('.process-figure')||panel.querySelector('.process-tab-placeholder');
   if(!visual)return;
   visual.querySelector('figcaption')?.remove();
   visual.classList.add('mam-process-panel');
   visual.dataset.processPanel=tab.dataset.processTab;
   visual.setAttribute('aria-hidden','true');
   const step=document.createElement('article');
   step.className='mam-process-step';
   step.dataset.processStep=String(stepIndex);
   const title=document.createElement('h3');
   title.textContent=tab.textContent.trim();
   step.append(title,...captions.map(caption=>{
    const description=document.createElement('p');
    description.textContent=caption;
    return description;
   }));
   list.append(step);
   stage.append(visual);
   const trigger=document.createElement('div');
   trigger.className='mam-process-trigger';
   trigger.dataset.processStep=String(stepIndex);
   triggers.append(trigger);
   stepIndex++;
  });
  copy.append(groupLabel,list);
  story.append(copy,stage,triggers);
  stories.push(story);
 });
 if(!stories.length)return;
 const container=document.createElement('div');
 container.className='mam-process-stories';
 container.append(...stories);
 section.classList.add('mam-process-section');
 section.querySelector('.case-content')?.remove();
 section.querySelector('.process-groups')?.remove();
 section.append(container);
 stories.forEach(story=>{
  const copySteps=[...story.querySelectorAll('.mam-process-step')];
  const panels=[...story.querySelectorAll('.mam-process-panel')];
  const activate=index=>{
   copySteps.forEach((step,i)=>{
    const active=i===index;
    step.classList.toggle('is-active',active);
    if(active)step.setAttribute('aria-current','step');else step.removeAttribute('aria-current');
   });
   panels.forEach((panel,i)=>{
    const active=i===index;
    panel.classList.toggle('is-active',active);
    panel.setAttribute('aria-hidden',String(!active));
   });
  };
  const triggers=[...story.querySelectorAll('.mam-process-trigger')];
  const goToStep=index=>{
   const trigger=triggers[index];
   if(!trigger)return;
   const top=trigger.getBoundingClientRect().top+scrollY;
   window.scrollTo({top,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});
  };
  copySteps.forEach((step,index)=>{
   step.setAttribute('role','button');
   step.tabIndex=0;
   step.addEventListener('click',()=>goToStep(index));
   step.addEventListener('keydown',event=>{
    if(event.key!=='Enter'&&event.key!==' ')return;
    event.preventDefault();
    goToStep(index);
   });
  });
  const stepObserver=new IntersectionObserver(entries=>{
   const visible=entries.filter(entry=>entry.isIntersecting);
   visible.sort((a,b)=>Math.abs(a.boundingClientRect.top+a.boundingClientRect.height/2-innerHeight*.5)-Math.abs(b.boundingClientRect.top+b.boundingClientRect.height/2-innerHeight*.5));
   if(visible[0])activate(Number(visible[0].target.dataset.processStep)-Number(triggers[0].dataset.processStep));
  },{rootMargin:'-42% 0px -42% 0px',threshold:0.01});
  triggers.forEach(trigger=>stepObserver.observe(trigger));
  mamProcessObservers.push(stepObserver);
  activate(0);
 });
}

function renderSnuffedAppScreen(page,index){return `<article class="snuffed-app-copy-step" data-app-step="${index}"><span class="snuffed-app-step">${String(index+1).padStart(2,'0')} / ${String(6).padStart(2,'0')}</span><h3>${page.title}</h3><p>${page.text}</p></article>`}
function enhanceSnuffedAppGallery(root){const gallery=root.querySelector('.snuffed-app-sequence');if(!gallery)return;const steps=[...gallery.querySelectorAll('[data-app-step]')],screens=[...gallery.querySelectorAll('[data-app-screen]')];if(!steps.length||!screens.length)return;snuffedAppObserver?.disconnect();const activate=index=>{steps.forEach((step,i)=>{const active=i===index;step.classList.toggle('is-active',active);if(active)step.setAttribute('aria-current','step');else step.removeAttribute('aria-current')});screens.forEach((screen,i)=>{const active=i===index;screen.classList.toggle('is-active',active);if(active)screen.removeAttribute('aria-hidden');else screen.setAttribute('aria-hidden','true')})};activate(0);snuffedAppObserver=new IntersectionObserver(entries=>{const visible=entries.filter(entry=>entry.isIntersecting);if(!visible.length)return;visible.sort((a,b)=>b.intersectionRatio-a.intersectionRatio);activate(Number(visible[0].target.dataset.appStep))},{rootMargin:'-32% 0px -32% 0px',threshold:[0,.2,.4,.6,.8,1]});steps.forEach(step=>snuffedAppObserver.observe(step))}
