function enhanceMamImpact(section){
 const rows=[...section.querySelectorAll('.mam-impact-row')];
 if(!rows.length)return;
 let started=false;
 const animate=()=>{
  if(started)return;
  started=true;
  const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
  const revealRow=index=>{
   const row=rows[index],counter=row?.querySelector('[data-countup]');
   if(!row||!counter)return;
   const target=Number(counter.dataset.countup);
   row.classList.add('is-visible');
   if(reduced){counter.textContent=String(target);if(index+1<rows.length)revealRow(index+1);return}
   const start=performance.now(),duration=950;
   const tick=now=>{
    const progress=Math.min(1,(now-start)/duration);
    counter.textContent=String(Math.round(target*(1-Math.pow(1-progress,3))));
    if(progress<1)requestAnimationFrame(tick);
    else{counter.textContent=String(target);if(index+1<rows.length)setTimeout(()=>revealRow(index+1),220)}
   };
   requestAnimationFrame(tick);
  };
  revealRow(0);
 };
 if('IntersectionObserver'in window){
  const observer=new IntersectionObserver(entries=>{
   if(entries.some(entry=>entry.isIntersecting)){animate();observer.disconnect()}
  },{threshold:.2});
  observer.observe(section);
 }else animate();
}
function enhanceDownloadsMetric(metric){
 const line=metric.querySelector('.downloads-line');
 if(!line)return;
 line.style.setProperty('--line-length',line.getTotalLength());
 const reveal=()=>metric.classList.add('is-revealed');
 if(matchMedia('(prefers-reduced-motion: reduce)').matches){reveal();return}
 if('IntersectionObserver'in window){const observer=new IntersectionObserver(entries=>{if(entries.some(entry=>entry.isIntersecting)){reveal();observer.disconnect()}},{threshold:.35});observer.observe(metric)}else reveal();
}
function about(){
 const aboutSlides=[
  ['natural-habitat.jpg','Me in my natural habitat'],
  ['creative-recruitment.jpg','Just finished up running recruitment for the Creative Design team of one of my clubs!'],
  ['study-abroad-spain.jpg','Snapshot of my study abroad in Spain this past summer'],
  ['study-abroad-friends.jpg','Me, my professor, and some of my study abroad friends!'],
  ['pool.jpg','Fun fact: I love playing pool :))'],
  ['daniel-caesar.jpg','My favorite artist is Daniel Caesar, and I went to his concert this summer!'],
  ['pickleball.jpg',"I'm not a very athletic person but the passion is there..."]
 ];
 const slidesMarkup=aboutSlides.map(([image,caption],index)=>`<figure class="about-slide${index===0?' is-active':''}" data-about-slide="${index}" aria-hidden="${index!==0}"><img src="${base}assets/media/about/${image}" alt="${caption}" ${index===0?'fetchpriority="high"':'loading="lazy"'}><figcaption>${caption}</figcaption></figure>`).join('');
 root.innerHTML=`${transitionPreview?'':nav('about')}${transitionPreview?'':sideOverview(false,true)}${transitionPreview?'':sideWeather()}<main id="top" class="wrap page-with-rail about-main${transitionPreview?' transition-about':''}"><header class="page-head"><div class="eyebrow">ABOUT</div><h1>It's lovely to meet you!</h1></header><div class="about-grid"><section class="about-slideshow" aria-label="A few things about me"><div class="about-slideshow-stage" role="region" aria-roledescription="carousel" aria-label="About me photo slideshow">${slidesMarkup}</div></section><div class="bodycopy"><div class="eyebrow">Background</div><p>As a first-generation college student who grew up in an immigrant family, I've witnessed firsthand how unnecessary friction gets in the way of great things – opportunities, resources, and ideas alike. I learned to really value moments when things click and feel easy, so now I design products that allow make everyday experiences simpler and more joyful to reach — this way, they can spend less time and effort struggling and more time enjoying what they love.</p><div class="eyebrow">Toolkit</div><div class="chips">${'Product Design,UX Research,UI Design,Design Engineering,Graphic Design,Industrial Design,Prompt Engineering,Marketing,Branding,Figma,Figma Make,Framer,Adobe Suite,Python,JavaScript,HTML/CSS'.split(',').map(x=>`<span>${x}</span>`).join('')}</div><div class="eyebrow">Interests</div><div class="chips">${'Photography,Reading,R&B Music,Extra Spice,Teaching,Stationary,8-ball,Typography,Journaling'.split(',').map(x=>`<span>${x}</span>`).join('')}</div></div></div><section class="section about-leadership"><h2>Leadership</h2><div class="about-leadership-grid">${[['MICHIGAN ADVERTISING AND MARKETING','VP Creative Design · Marketing consultation for Ann Arbor businesses. I lead creative deliverables and mentor members.','https://umichmam.org/'],['MAIZEBUS','UX/UI Designer · Designed for students, by students, MaizeBus makes navigating the University of Michigan campus easier.','https://maizebus.com/'],['FIGMA CAMPUS LEADER','Building a campus design community through events, resources, and Figma education.','https://www.figma.com/community/']].map(([n,t,u])=>`<a class="about-leadership-card" href="${u}" target="_blank" rel="noreferrer"><b>${n}<span aria-hidden="true">↗</span></b><span>${t}</span></a>`).join('')}</div></section></main>`;
 startSideInfo();initAboutSlideshow();
}
function initAboutSlideshow(){
 const slideshow=document.querySelector('.about-slideshow');if(!slideshow)return;
 const slides=[...slideshow.querySelectorAll('[data-about-slide]')];
 if(slides.length<2||window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;
 let current=0,timer=null;
 const advance=()=>{const next=(current+1)%slides.length;slides[current].classList.remove('is-active');slides[current].setAttribute('aria-hidden','true');slides[next].classList.add('is-active');slides[next].setAttribute('aria-hidden','false');current=next};
 const stop=()=>{clearInterval(timer);timer=null};
 const start=()=>{stop();if(!document.hidden)timer=setInterval(advance,5000)};
 document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();else start()});
 start();
}
